/* ===== Orchard Design System ===== */

:root {
  --color-dark: #1d1d1f;
  --color-secondary: #6e6e73;
  --color-light-bg: #f5f5f7;
  --color-white: #ffffff;
  --color-blue: #0066cc;
  --color-blue-hover: #004499;
  --color-border: #d2d2d7;
  --color-ribbon-bg: #1d1d1f;
  --color-ribbon-text: #f5f5f7;

  --font-stack: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;

  --nav-height: 44px;
  --section-nav-height: 52px;

  --max-width: 1200px;
  --carousel-card-width: 280px;
  --carousel-gap: 16px;

  --transition-fast: 0.2s ease;
  --transition-medium: 0.35s ease;
}

/* Reset */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body { font-family: var(--font-stack); color: var(--color-dark); background: var(--color-white); line-height: 1.5; -webkit-font-smoothing: antialiased; }
a { color: var(--color-blue); text-decoration: none; }
a:hover { text-decoration: underline; }
img { max-width: 100%; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* ===== Top Navigation ===== */
.top-nav {
  background: rgba(29,29,31,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  height: var(--nav-height);
  position: sticky;
  top: 0;
  z-index: 1000;
}
.top-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  padding: 0 22px;
}
.top-nav .logo {
  font-size: 18px;
  font-weight: 600;
  color: var(--color-light-bg);
  letter-spacing: -0.02em;
}
.top-nav .nav-links {
  display: flex;
  gap: 24px;
  align-items: center;
}
.top-nav .nav-links a {
  color: rgba(245,245,247,0.8);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0;
  transition: color var(--transition-fast);
}
.top-nav .nav-links a:hover {
  color: #fff;
  text-decoration: none;
}
.nav-icon {
  width: 18px;
  height: 18px;
  fill: rgba(245,245,247,0.8);
}

/* ===== Ribbon Banner ===== */
.ribbon-banner {
  background: var(--color-ribbon-bg);
  color: var(--color-ribbon-text);
  text-align: center;
  padding: 12px 22px;
  font-size: 14px;
  line-height: 1.5;
}
.ribbon-banner a {
  color: var(--color-blue);
  font-weight: 500;
}

/* ===== Hero Section ===== */
.hero-section {
  text-align: center;
  padding: 80px 22px 60px;
  background: var(--color-white);
}
.hero-section h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.05;
  margin-bottom: 8px;
}
.hero-section .hero-sub {
  font-size: 28px;
  font-weight: 400;
  color: var(--color-secondary);
  max-width: 600px;
  margin: 0 auto 24px;
  line-height: 1.2;
}
.hero-ctas {
  display: flex;
  gap: 20px;
  justify-content: center;
  flex-wrap: wrap;
}
.hero-ctas a {
  font-size: 17px;
  font-weight: 400;
}

/* ===== Product Grid (Homepage) ===== */
.product-grid {
  max-width: 1120px;
  margin: 0 auto;
  padding: 0 22px 60px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.product-tile {
  border-radius: 20px;
  overflow: hidden;
  text-align: center;
  padding: 44px 30px 36px;
  min-height: 500px;
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
}
.product-tile.bg-light { background: var(--color-light-bg); }
.product-tile.bg-dark { background: var(--color-dark); color: #fff; }
.product-tile.bg-gradient-1 { background: linear-gradient(180deg, #f5e6d3 0%, #f5f5f7 100%); }
.product-tile.bg-gradient-2 { background: linear-gradient(180deg, #d4e8f7 0%, #f5f5f7 100%); }
.product-tile.bg-gradient-3 { background: linear-gradient(180deg, #e8d4f5 0%, #f5f5f7 100%); }
.product-tile.bg-gradient-4 { background: linear-gradient(180deg, #f5d4d4 0%, #f5f5f7 100%); }
.product-tile.bg-gradient-5 { background: linear-gradient(180deg, #d4f5e0 0%, #f5f5f7 100%); }
.product-tile.bg-gradient-6 { background: linear-gradient(180deg, #1d1d1f 0%, #2d2d2f 100%); color: #fff; }

.product-tile .tile-badge {
  display: inline-block;
  background: var(--color-blue);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 10px;
  margin-bottom: 10px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.product-tile h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
  margin-bottom: 6px;
}
.product-tile .tile-tagline {
  font-size: 21px;
  font-weight: 400;
  color: var(--color-secondary);
  margin-bottom: 4px;
}
.product-tile.bg-dark .tile-tagline,
.product-tile.bg-gradient-6 .tile-tagline { color: rgba(255,255,255,0.7); }
.product-tile .tile-price {
  font-size: 14px;
  margin-bottom: 16px;
  color: var(--color-secondary);
}
.product-tile.bg-dark .tile-price,
.product-tile.bg-gradient-6 .tile-price { color: rgba(255,255,255,0.6); }
.tile-ctas {
  display: flex;
  gap: 20px;
  margin-top: auto;
}
.tile-ctas a {
  font-size: 17px;
}
.tile-ctas .cta-buy {
  background: var(--color-blue);
  color: #fff;
  padding: 8px 22px;
  border-radius: 980px;
  font-weight: 400;
  transition: background var(--transition-fast);
}
.tile-ctas .cta-buy:hover { background: var(--color-blue-hover); text-decoration: none; }
.product-tile .product-image {
  margin-top: 20px;
  width: 70%;
  max-width: 340px;
  aspect-ratio: 4/3;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}

/* ===== Section Styles ===== */
.section {
  padding: 60px 0;
}
.section-heading {
  text-align: center;
  margin-bottom: 8px;
}
.section-heading h2 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.08;
}
.section-subheading {
  text-align: center;
  color: var(--color-secondary);
  font-size: 21px;
  margin-bottom: 32px;
}
.section-promo {
  text-align: center;
  color: var(--color-secondary);
  font-size: 14px;
  margin-top: 16px;
}
.section-promo a { color: var(--color-blue); }

/* ===== Carousel ===== */
.carousel-section {
  position: relative;
  padding: 0 0 60px;
}
.carousel-header {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 52px 16px;
}
.carousel-header h2 {
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.carousel-header p {
  color: var(--color-secondary);
  font-size: 17px;
  margin-top: 4px;
}
.carousel-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
}
.carousel-track-container {
  overflow: hidden;
  padding: 0 52px;
}
.carousel-track {
  display: flex;
  gap: var(--carousel-gap);
  transition: transform 0.45s cubic-bezier(0.25, 0.1, 0.25, 1);
  will-change: transform;
}
.carousel-card {
  flex: 0 0 var(--carousel-card-width);
  background: var(--color-light-bg);
  border-radius: 20px;
  overflow: hidden;
  cursor: pointer;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}
.carousel-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(0,0,0,0.08);
}
.card-image {
  width: 100%;
  aspect-ratio: 1/1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 56px;
  background: var(--color-white);
  position: relative;
}
.card-image .card-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--color-blue);
  color: #fff;
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 8px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.card-body {
  padding: 16px 18px 20px;
}
.card-body h3 {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
  margin-bottom: 4px;
}
.card-body .card-tagline {
  font-size: 13px;
  color: var(--color-secondary);
  margin-bottom: 8px;
  line-height: 1.35;
}
.card-body .card-price {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 2px;
}
.card-body .card-monthly {
  font-size: 12px;
  color: var(--color-secondary);
}
.card-body .card-note {
  font-size: 11px;
  color: var(--color-secondary);
  margin-top: 6px;
}
.card-body .card-cta {
  display: inline-block;
  font-size: 13px;
  color: var(--color-blue);
  margin-top: 8px;
}

/* Carousel Arrows */
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: background var(--transition-fast), box-shadow var(--transition-fast);
  box-shadow: 0 1px 4px rgba(0,0,0,0.1);
}
.carousel-btn:hover {
  background: #fff;
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}
.carousel-btn.prev { left: 4px; }
.carousel-btn.next { right: 4px; }
.carousel-btn svg {
  width: 16px;
  height: 16px;
  stroke: var(--color-dark);
  stroke-width: 2.5;
  fill: none;
}
.carousel-btn:disabled {
  opacity: 0.3;
  cursor: default;
  pointer-events: none;
}

/* ===== Product Icon Bar ===== */
.icon-bar {
  background: var(--color-white);
  border-bottom: 1px solid var(--color-border);
  padding: 16px 0;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar-inner {
  display: flex;
  justify-content: center;
  gap: 28px;
  padding: 0 22px;
  min-width: max-content;
}
.icon-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-decoration: none;
  color: var(--color-dark);
  transition: color var(--transition-fast);
}
.icon-bar-item:hover { text-decoration: none; color: var(--color-blue); }
.icon-bar-item .icon-img {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}
.icon-bar-item .icon-label {
  font-size: 11px;
  font-weight: 500;
  white-space: nowrap;
}

/* ===== Entertainment Tabs ===== */
.entertainment-section {
  background: var(--color-white);
  padding: 60px 0;
}
.entertainment-header {
  text-align: center;
  margin-bottom: 24px;
}
.entertainment-header h2 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.03em;
}
.ent-tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 32px;
}
.ent-tab {
  padding: 8px 20px;
  font-size: 14px;
  font-weight: 500;
  border-radius: 980px;
  color: var(--color-dark);
  background: var(--color-light-bg);
  transition: all var(--transition-fast);
}
.ent-tab:hover { text-decoration: none; background: #e8e8ed; }
.ent-tab.active {
  background: var(--color-dark);
  color: #fff;
}
.ent-content {
  display: none;
}
.ent-content.active {
  display: block;
}
.ent-cards {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.ent-card {
  border-radius: 16px;
  overflow: hidden;
  position: relative;
  aspect-ratio: 2/3;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 20px;
  color: #fff;
  cursor: pointer;
}
.ent-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0) 50%);
  z-index: 1;
}
.ent-card > * { position: relative; z-index: 2; }
.ent-card h3 { font-size: 18px; font-weight: 600; margin-bottom: 4px; }
.ent-card p { font-size: 13px; opacity: 0.85; margin-bottom: 10px; }
.ent-card .ent-cta {
  font-size: 13px;
  color: #fff;
  font-weight: 500;
  text-decoration: underline;
}

/* ===== Help Cards ===== */
.help-cards {
  display: flex;
  gap: var(--carousel-gap);
  overflow-x: auto;
  padding: 0 52px 8px;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.help-cards::-webkit-scrollbar { display: none; }

.help-card {
  flex: 0 0 260px;
  background: var(--color-light-bg);
  border-radius: 20px;
  padding: 28px 24px;
  scroll-snap-align: start;
}
.help-card .help-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: var(--color-blue);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  margin-bottom: 16px;
}
.help-card h3 { font-size: 17px; font-weight: 600; margin-bottom: 6px; }
.help-card p { font-size: 14px; color: var(--color-secondary); line-height: 1.45; }

/* ===== Store Difference ===== */
.diff-cards {
  display: flex;
  gap: var(--carousel-gap);
  overflow-x: auto;
  padding: 0 52px 8px;
  scrollbar-width: none;
}
.diff-cards::-webkit-scrollbar { display: none; }
.diff-card {
  flex: 0 0 240px;
  background: var(--color-light-bg);
  border-radius: 20px;
  padding: 28px 24px;
  text-align: center;
}
.diff-card .diff-icon {
  font-size: 36px;
  margin-bottom: 12px;
}
.diff-card h3 { font-size: 15px; font-weight: 600; margin-bottom: 6px; }
.diff-card p { font-size: 13px; color: var(--color-secondary); line-height: 1.4; }

/* ===== Brand Collab ===== */
.brand-collab {
  background: var(--color-dark);
  color: #fff;
  padding: 80px 22px;
  text-align: center;
}
.brand-collab h2 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.03em;
  margin-bottom: 8px;
}
.brand-collab p {
  font-size: 21px;
  color: rgba(255,255,255,0.7);
  max-width: 600px;
  margin: 0 auto 24px;
}
.brand-collab .collab-items {
  display: flex;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
  margin-top: 32px;
}
.brand-collab .collab-item {
  background: rgba(255,255,255,0.1);
  border-radius: 16px;
  padding: 24px;
  text-align: center;
  width: 200px;
}
.brand-collab .collab-item .item-icon { font-size: 40px; margin-bottom: 10px; }
.brand-collab .collab-item h3 { font-size: 15px; font-weight: 600; }

/* ===== Experience Section ===== */
.experience-section {
  background: var(--color-light-bg);
  padding: 60px 22px;
  text-align: center;
}
.experience-section h2 {
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}
.experience-section p {
  color: var(--color-secondary);
  font-size: 17px;
  max-width: 500px;
  margin: 0 auto;
}

/* ===== Quick Links ===== */
.quick-links {
  padding: 40px 22px;
  border-top: 1px solid var(--color-border);
}
.quick-links-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  justify-content: center;
  gap: 32px;
  flex-wrap: wrap;
}
.quick-link {
  font-size: 14px;
  color: var(--color-blue);
  display: flex;
  align-items: center;
  gap: 6px;
}

/* ===== Category Page Sticky Nav ===== */
.section-nav-wrapper {
  position: sticky;
  top: var(--nav-height);
  z-index: 900;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
}
.section-nav {
  display: flex;
  gap: 28px;
  padding: 0 22px;
  overflow-x: auto;
  scrollbar-width: none;
  justify-content: center;
  max-width: var(--max-width);
  margin: 0 auto;
}
.section-nav::-webkit-scrollbar { display: none; }
.section-nav a {
  font-size: 13px;
  font-weight: 500;
  color: var(--color-secondary);
  padding: 14px 0;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
}
.section-nav a:hover,
.section-nav a.active {
  color: var(--color-dark);
  text-decoration: none;
  border-bottom-color: var(--color-dark);
}

/* ===== Category Hero ===== */
.category-hero {
  text-align: center;
  padding: 64px 22px 48px;
  background: var(--color-light-bg);
}
.category-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.05;
}
.category-hero p {
  font-size: 21px;
  color: var(--color-secondary);
  margin-top: 8px;
}

/* ===== Shopping Guides ===== */
.guide-cards {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 52px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
}
.guide-card {
  background: var(--color-light-bg);
  border-radius: 16px;
  padding: 28px 22px;
  text-align: center;
}
.guide-card .guide-icon {
  font-size: 36px;
  margin-bottom: 12px;
}
.guide-card h3 { font-size: 16px; font-weight: 600; margin-bottom: 6px; }
.guide-card p { font-size: 13px; color: var(--color-secondary); line-height: 1.4; }

/* ===== Ways to Save ===== */
.save-cards {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 52px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}
.save-card {
  background: var(--color-light-bg);
  border-radius: 16px;
  padding: 24px 20px;
  text-align: center;
}
.save-card .save-icon { font-size: 32px; margin-bottom: 10px; }
.save-card h3 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.save-card p { font-size: 13px; color: var(--color-secondary); line-height: 1.35; }

/* ===== Setup Support ===== */
.setup-section {
  background: var(--color-light-bg);
  padding: 60px 22px;
  text-align: center;
}
.setup-section h2 {
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}
.setup-section p {
  color: var(--color-secondary);
  font-size: 17px;
  max-width: 500px;
  margin: 0 auto 20px;
}
.setup-section .setup-ctas a {
  font-size: 17px;
}

/* ===== Special Stores ===== */
.special-stores {
  padding: 60px 22px;
  text-align: center;
}
.special-stores h2 {
  font-size: 32px;
  font-weight: 700;
  margin-bottom: 24px;
}
.stores-grid {
  max-width: 800px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
}
.store-link {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 18px;
  background: var(--color-light-bg);
  border-radius: 12px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-dark);
  transition: background var(--transition-fast);
}
.store-link:hover {
  background: #e8e8ed;
  text-decoration: none;
}

/* ===== Footer ===== */
.site-footer {
  background: var(--color-light-bg);
  padding: 24px 22px 16px;
  border-top: 1px solid var(--color-border);
}
.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}
.footer-legal {
  font-size: 12px;
  color: var(--color-secondary);
  line-height: 1.55;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 20px;
}
.footer-columns {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 20px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 16px;
}
.footer-col h4 {
  font-size: 12px;
  font-weight: 600;
